using System;
using System.IO;
using System.Collections.Generic;
using DualDiscord;
static class FlexibilityTests {
 static int failed,total;static string root;
 static void Check(string name,Action action){total++;try{action();Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
 static void Assert(bool value){if(!value)throw new Exception("Assertion failed");}
 static void Reject(Action action){try{action();}catch(IOException){return;}throw new Exception("Expected safe rejection");}
 static void Junction(string path,string target){using(var process=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("cmd.exe","/c mklink /J \""+path+"\" \""+target+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true})){process.StandardOutput.ReadToEnd();process.WaitForExit();if(process.ExitCode!=0)throw new Exception("Fixture junction failed");}}
 public static int Run(){root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"DualFlex-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
  Check("Customization defaults preserve combined sync and enable update checks",()=>{var c=new Customization();Assert(c.AutoCheckUpdates&&c.SyncAudio&&c.SyncGraphics&&!c.CopyThemes);});
  Check("Fresh profile defaults inside installation",()=>Assert(ProfileStorage.Resolve(null,Path.Combine(root,"Missing"),root)==Path.Combine(root,"Profiles","Second")));
  Check("Existing legacy profile remains selected",()=>{string legacy=Path.Combine(root,"Legacy");Directory.CreateDirectory(Path.Combine(legacy,"discord"));Assert(ProfileStorage.Resolve(null,legacy,root)==legacy);});
  Check("Saved profile location takes precedence",()=>Assert(ProfileStorage.Resolve(Path.Combine(root,"Custom"),root,root)==Path.Combine(root,"Custom")));
  Check("Relocation retains source and verifies all copied data",()=>{string source=Path.Combine(root,"Source"),target=Path.Combine(root,"Target");Directory.CreateDirectory(Path.Combine(source,"discord","Network"));File.WriteAllText(Path.Combine(source,"discord","Network","test"),"private fixture");ProfileStorage.CopyVerified(source,target,new[]{Path.Combine(root,"Protected")});Assert(File.ReadAllText(Path.Combine(target,"discord","Network","test"))=="private fixture"&&File.Exists(Path.Combine(source,"discord","Network","test")));});
  Check("Nonempty relocation destination is never overwritten",()=>Reject(()=>ProfileStorage.CopyVerified(Path.Combine(root,"Source"),Path.Combine(root,"Target"),new string[0])));
  Check("Nested source destination is rejected",()=>Reject(()=>ProfileStorage.CopyVerified(Path.Combine(root,"Source"),Path.Combine(root,"Source","Nested"),new string[0])));
  Check("Main profile ancestors are protected even when empty",()=>{string target=Path.Combine(root,"EmptyAncestor");Directory.CreateDirectory(target);Reject(()=>ProfileStorage.CopyVerified(Path.Combine(root,"Source"),target,new[]{Path.Combine(target,"Main")}));});
  Check("Main profile descendants are protected",()=>Reject(()=>ProfileStorage.CopyVerified(Path.Combine(root,"Source"),Path.Combine(root,"ProtectedMain","Child"),new[]{Path.Combine(root,"ProtectedMain")})));
  Check("Missing source is never silently replaced with a blank profile",()=>Reject(()=>ProfileStorage.CopyVerified(Path.Combine(root,"MissingSource"),Path.Combine(root,"MissingTarget"),new string[0])));
  Check("Sharing selects supported keys without account fields",()=>{var c=new Customization{SyncAudio=false,SyncGraphics=true};var source=new Dictionary<string,object>{{"audioSubsystem","legacy"},{"enableHardwareAcceleration",false},{"token","secret"},{"MINIMIZE_TO_TRAY",false}};var target=new Dictionary<string,object>{{"token","own"}};PreferenceSharing.Apply(source,target,c);Assert(!target.ContainsKey("audioSubsystem")&&target.ContainsKey("enableHardwareAcceleration")&&(string)target["token"]=="own"&&!target.ContainsKey("MINIMIZE_TO_TRAY"));});
  Check("Theme copying excludes settings and preserves overwritten CSS",()=>{string source=Path.Combine(root,"ThemesMain"),target=Path.Combine(root,"ThemesSecond");Directory.CreateDirectory(source);Directory.CreateDirectory(target);File.WriteAllText(Path.Combine(source,"one.css"),"new");File.WriteAllText(Path.Combine(source,"settings.json"),"never");File.WriteAllText(Path.Combine(target,"one.css"),"old");PreferenceSharing.CopyThemes(source,target);Assert(File.ReadAllText(Path.Combine(target,"one.css"))=="new"&&!File.Exists(Path.Combine(target,"settings.json"))&&Directory.GetFiles(Path.Combine(target,"Backups"),"*.css",SearchOption.AllDirectories).Length==1);});
  Check("Relocation protects paths behind directory aliases",()=>{string real=Path.Combine(root,"RealProtected"),alias=Path.Combine(root,"AliasProtected");Directory.CreateDirectory(real);Junction(alias,real);Reject(()=>ProfileStorage.CopyVerified(Path.Combine(root,"Source"),Path.Combine(alias,"Child"),new[]{real}));});
  Check("Relocation refuses linked contents",()=>{string source=Path.Combine(root,"LinkedSource");Directory.CreateDirectory(source);Junction(Path.Combine(source,"link"),Path.Combine(root,"Source"));Reject(()=>ProfileStorage.CopyVerified(source,source+"-target",new string[0]));});
  Check("Theme backups cannot redirect writes through a link",()=>{string source=Path.Combine(root,"ThemeLinkSource"),target=Path.Combine(root,"ThemeLinkTarget"),outside=Path.Combine(root,"Outside");Directory.CreateDirectory(source);Directory.CreateDirectory(target);Directory.CreateDirectory(outside);File.WriteAllText(Path.Combine(source,"one.css"),"new");File.WriteAllText(Path.Combine(target,"one.css"),"old");Junction(Path.Combine(target,"Backups"),outside);Reject(()=>PreferenceSharing.CopyThemes(source,target));Assert(File.ReadAllText(Path.Combine(target,"one.css"))=="old"&&Directory.GetFileSystemEntries(outside).Length==0);});
  Check("Customization round trips separately",()=>{string file=Path.Combine(root,"customization.json");Customization.Save(file,new Customization{SecondRoot=Path.Combine(root,"Custom"),SyncAudio=false});var value=Customization.Load(file);Assert(!value.SyncAudio&&value.SecondRoot.EndsWith("Custom")&&value.AutoCheckUpdates);});
  Check("Automatic update policy throttles and honors opt out",()=>{var policy=new UpdateSchedule();var now=DateTime.UtcNow;Assert(!policy.TakeCheck(false,now)&&policy.TakeCheck(true,now)&&!policy.TakeCheck(true,now.AddMinutes(1))&&policy.TakeCheck(true,now.AddHours(6)));});
  Check("A dismissed release is not announced repeatedly in a session",()=>{var policy=new UpdateSchedule();Assert(policy.Announce("2.2.0")&&!policy.Announce("2.2.0")&&policy.Announce("2.2.1"));});
  Console.WriteLine("FLEXIBILITY "+(total-failed)+" passed, "+failed+" failed");return failed;
 }
}
